"use client";
import { useState } from "react";
import Link from "next/link";
import { logActivity, resetDb, setDb, useSlice } from "@/lib/biz/db";
import { qtyAt, stockMap } from "@/lib/biz/inv-calc";
import type { PurchaseOrder, ReqLine, Requisition, Supplier } from "@/lib/biz/seed-proc";
import { DEMO_TODAY, addDays, daysBetween, downloadCsv, downloadJson, emailOk, fmtDate, groupBy, lastNMonths, money, moneyK, monthKey, monthLabel, pct, round2, sum, uid } from "@/lib/biz/util";
import type { Branding } from "@/lib/types";
import { AppProviders, AreaIn, Badge, BarChart, BrandLogo, Btn, DataTable, DemoBadge, DemoLinks, Drawer, Empty, FilterSelect, Kpi, KpiRow, Modal, Notice, PageHead, Panel, PrintSheet, ResetButton, SelectIn, Tabs, TextIn, Timeline, printNow, useConfirm, useToast, type Col } from "./kit";

/* Procurement workflow workspace: a stage funnel runs under the header on every screen; the home screen is one unified work queue, and each purchase order opens as a document page with its lifecycle and stock impact. */
const TAX = 0.08;
const SECTIONS = [{ id: "pipeline", label: "Pipeline" }, { id: "reqs", label: "Requisitions" }, { id: "orders", label: "Purchase orders" }, { id: "receipts", label: "Deliveries" }, { id: "approvals", label: "Approvals" }, { id: "suppliers", label: "Suppliers" }, { id: "reports", label: "Reports" }];
const STAGES = ["Requisition", "Pending Approval", "Approved", "Ordered", "Partially Received", "Completed"] as const; type Stage = (typeof STAGES)[number];
const STAGE_TONE: Record<Stage, "slate" | "amber" | "blue" | "violet" | "green"> = { Requisition: "slate", "Pending Approval": "amber", Approved: "blue", Ordered: "violet", "Partially Received": "amber", Completed: "green" };
const M = (n: number) => money(n);
const poTone = (s: string) => (s === "Received" ? "green" : s === "Partially received" ? "amber" : s === "Sent" ? "blue" : s === "Cancelled" ? "red" : "slate") as "green" | "amber" | "blue" | "red" | "slate";
const rqTone = (s: string) => (s === "Approved" || s === "Converted" ? "green" : s === "Rejected" ? "red" : s === "Submitted" ? "amber" : "slate") as "green" | "red" | "amber" | "slate";
const linesTotal = (l: { qty: number; price: number }[]) => { const subtotal = round2(sum(l, (x) => x.qty * x.price)), tax = round2(subtotal * TAX); return { subtotal, tax, total: round2(subtotal + tax) }; };

type Item = { key: string; kind: "Requisition" | "Purchase order"; id: string; number: string; party: string; amount: number; stage: Stage; date: string; next: string; late: boolean };
function useItems(): Item[] {
  const { proc, sName, eName } = useP(); const items: Item[] = [];
  for (const r of proc.requisitions) { const stage: Stage | null = r.status === "Draft" ? "Requisition" : r.status === "Submitted" ? "Pending Approval" : r.status === "Approved" ? "Approved" : null; if (stage) items.push({ key: r.id, kind: "Requisition", id: r.id, number: r.number, party: `${eName(r.requesterId)} · ${r.dept}`, amount: linesTotal(r.lines).total, stage, date: r.date, next: r.status === "Draft" ? "Submit for approval" : r.status === "Submitted" ? "Approve or reject" : "Convert to purchase order", late: false }); }
  for (const o of proc.orders) { const stage: Stage | null = o.status === "Draft" ? "Approved" : o.status === "Sent" ? "Ordered" : o.status === "Partially received" ? "Partially Received" : o.status === "Received" ? "Completed" : null; if (stage) items.push({ key: o.id, kind: "Purchase order", id: o.id, number: o.number, party: sName(o.supplierId), amount: linesTotal(o.lines).total, stage, date: o.expected, next: o.status === "Draft" ? "Send to supplier" : o.status === "Sent" ? "Record delivery" : o.status === "Partially received" ? "Record remaining delivery" : "None", late: live(o) && o.expected < DEMO_TODAY }); }
  return items;
}

export default function ProcurementApp({ branding }: { branding: Branding }) {
  return (
    <AppProviders className="bg-stone-100 text-slate-800" note="Demonstration procurement software. Approvals, orders and deliveries are simulated: nothing is sent to suppliers. A goods receipt adds stock to the Inventory demo (shared local data).">
      <Workspace branding={branding} />
    </AppProviders>
  );
}
function Workspace({ branding }: { branding: Branding }) {
  const [screen, setScreen] = useState("pipeline"); const [sup, setSup] = useState<string | null>(null); const [po, setPo] = useState<string | null>(null); const [req, setReq] = useState<string | null>(null); const [stage, setStage] = useState<Stage | "">("");
  const { proc } = useP(); const items = useItems(); const pending = proc.requisitions.filter((r) => r.status === "Submitted").length;
  const openPo = (id: string) => { setPo(id); setScreen("po"); }; const openReq = (id: string) => { setReq(id); setScreen("reqs"); };
  const nav = (s: string) => { setScreen(s); setSup(null); setPo(null); setReq(null); };
  const active = screen === "supplier" ? "suppliers" : screen === "po" ? "orders" : screen;
  return (<>
    <header className="no-print border-b border-stone-300 bg-white">
      <div className="flex flex-wrap items-center gap-x-5 gap-y-2 px-5 py-3">
        <BrandLogo branding={branding} dark={false} height={28} />
        <div className="border-l border-stone-300 pl-5"><h1 className="font-display text-xl font-semibold leading-tight text-slate-900">NorthPeak Procurement</h1><p className="text-sm text-slate-600">Requisition to delivery · simulated approvals</p></div>
        <div className="ml-auto flex flex-wrap items-center gap-2"><DemoBadge /><ResetButton onReset={() => resetDb(["proc", "inv"])} label="Reset orders & stock" className="rounded-md border border-slate-300 px-3 py-1.5 text-sm font-medium text-slate-700 hover:border-blue-500" /><span className="flex gap-2 text-slate-700 [&_a]:border-slate-300"><DemoLinks compact /></span></div>
      </div>
      <nav aria-label="Procurement sections" className="flex flex-wrap gap-1 px-4">
        {SECTIONS.map((s) => <button key={s.id} type="button" data-nav={s.id} aria-current={active === s.id ? "page" : undefined} onClick={() => nav(s.id)} className={`-mb-px rounded-t-md border-x border-t px-4 py-2 text-[15px] font-medium ${active === s.id ? "border-stone-300 bg-stone-100 text-slate-900" : "border-transparent text-slate-600 hover:text-slate-900"}`}>{s.label}{s.id === "approvals" && pending > 0 && <span className="ml-2 rounded-full bg-amber-200 px-2 text-[13px] text-amber-900">{pending}</span>}</button>)}
      </nav>
    </header>
    <section aria-label="Procurement stages" className="no-print border-b border-stone-300 bg-stone-50 px-4 py-3">
      <ol className="flex gap-1 overflow-x-auto pb-1">
        {STAGES.map((st, i) => { const its = items.filter((x) => x.stage === st); const on = stage === st && screen === "pipeline"; return (
          <li key={st} className="min-w-[170px] flex-1"><button type="button" aria-pressed={on} data-testid={`stage-${st.toLowerCase().replace(/ /g, "-")}`} onClick={() => { setStage(on ? "" : st); setScreen("pipeline"); setPo(null); setReq(null); }}
            className={`relative block w-full border-2 px-4 py-2 text-left ${on ? "border-slate-900 bg-white shadow" : "border-stone-300 bg-white hover:border-slate-500"}`} style={{ clipPath: i === STAGES.length - 1 ? undefined : "polygon(0 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 0 100%)", borderRadius: 6 }}>
            <span className="flex items-center gap-1.5 text-[15px] font-semibold text-slate-900"><span className={`inline-block h-2.5 w-2.5 rounded-full ${st === "Completed" ? "bg-emerald-500" : st === "Pending Approval" || st === "Partially Received" ? "bg-amber-500" : st === "Ordered" ? "bg-violet-500" : st === "Approved" ? "bg-sky-500" : "bg-slate-400"}`} />{st}</span>
            <span className="mt-0.5 flex items-baseline gap-2"><span className="font-display text-2xl font-semibold tabular-nums" data-testid={`stage-count-${st.toLowerCase().replace(/ /g, "-")}`}>{its.length}</span><span className="text-sm text-slate-600 tabular-nums">{moneyK(sum(its, (x) => x.amount))}</span></span></button></li>); })}
      </ol>
    </section>
    <main className="min-w-0 flex-1 p-4 sm:p-6" id="app-main">
      {screen === "pipeline" && <Pipeline items={items} stage={stage} setStage={setStage} openPo={openPo} openReq={openReq} />}
      {screen === "reqs" && <Requisitions openPo={openPo} focus={req} />}
      {screen === "orders" && <Orders open={openPo} />}
      {screen === "po" && po && <PoPage id={po} back={() => nav("orders")} />}
      {screen === "receipts" && <Receipts openPo={openPo} />}
      {screen === "approvals" && <Approvals />}
      {screen === "suppliers" && <Suppliers open={(id) => { setSup(id); setScreen("supplier"); }} />}
      {screen === "supplier" && sup && <SupplierProfile id={sup} back={() => nav("suppliers")} openPo={openPo} />}
      {screen === "reports" && <Reports />}
    </main>
  </>);
}

/* ───────── Pipeline: one queue for everything in flight ───────── */
function Pipeline({ items, stage, setStage, openPo, openReq }: { items: Item[]; stage: Stage | ""; setStage(s: Stage | ""): void; openPo(id: string): void; openReq(id: string): void }) {
  const [kind, setKind] = useState(""); const rows = items.filter((i) => (!stage || i.stage === stage) && (!kind || i.kind === kind));
  const cols: Col<Item>[] = [{ key: "kind", label: "Type", render: (i) => <Badge tone={i.kind === "Purchase order" ? "violet" : "slate"}>{i.kind}</Badge> }, { key: "number", label: "Number", render: (i) => <span className="font-medium text-slate-900">{i.number}</span> }, { key: "party", label: "Supplier / requester" },
    { key: "amount", label: "Value incl. tax", align: "right", render: (i) => M(i.amount) }, { key: "stage", label: "Stage", render: (i) => <Badge tone={STAGE_TONE[i.stage]}>{i.stage}</Badge> }, { key: "date", label: "Date / expected", render: (i) => <span className={i.late ? "font-semibold text-red-700" : ""}>{fmtDate(i.date)}{i.late ? " · late" : ""}</span> }, { key: "next", label: "Next action", render: (i) => <span className="text-blue-700">{i.next}</span> }];
  return (<>
    <PageHead title={stage ? `${stage} (${rows.length})` : "Everything in flight"} sub={stage ? "Showing one stage. Select the stage again, or choose All, to clear the filter." : "Requisitions and purchase orders in a single queue, ordered by where they are in the process. Open one to take its next action."} actions={<><FilterSelect label="Type" value={kind} onChange={setKind} options={["Requisition", "Purchase order"]} />{stage && <Btn onClick={() => setStage("")}>All stages</Btn>}</>} />
    <DataTable rows={rows} columns={cols} rowKey={(i) => i.key} onRow={(i) => (i.kind === "Purchase order" ? openPo(i.id) : openReq(i.id))} exportName="procurement-pipeline" testid="pipeline-table" defaultSort={{ key: "stage", dir: 1 }} pageSize={12} searchPlaceholder="Search number or supplier…" />
  </>);
}

/* ───────── Purchase order page: lifecycle + document + stock impact ───────── */
const LIFE = ["Draft", "Sent", "Partially received", "Received"] as const;
function PoPage({ id, back }: { id: string; back(): void }) {
  const { proc, inv, pName, pSku } = useP(); const po = proc.orders.find((o) => o.id === id); const map = stockMap(inv.movements);
  if (!po) return <Empty>Purchase order not found. <Btn small onClick={back}>Back</Btn></Empty>;
  const idx = LIFE.indexOf(po.status as (typeof LIFE)[number]);
  return (<>
    <ol className="no-print mb-4 flex flex-wrap items-center gap-2" aria-label="Purchase order lifecycle">{po.status === "Cancelled" ? <li className="rounded-full bg-red-100 px-4 py-1.5 text-[15px] font-semibold text-red-700">Cancelled</li> : LIFE.map((s, i) => <li key={s} aria-current={i === idx ? "step" : undefined} className={`flex items-center gap-2 rounded-full px-4 py-1.5 text-[15px] font-medium ${i === idx ? "bg-slate-900 text-white" : i < idx ? "bg-emerald-100 text-emerald-900" : "bg-stone-200 text-slate-600"}`}>{i < idx ? "✓" : i + 1}<span>{s === "Sent" ? "Ordered (sent)" : s}</span></li>)}</ol>
    <PoDetail id={id} back={back} />
    <Panel title="Stock impact in Inventory" className="mt-4" pad={false}>
      <table className="w-full text-[15px]" data-testid="po-stock-impact"><thead className="bg-stone-50 text-left text-sm text-slate-600"><tr><th className="p-2.5">Product</th><th className="p-2.5 text-right">Ordered</th><th className="p-2.5 text-right">Received</th><th className="p-2.5 text-right">Still due</th><th className="p-2.5 text-right">On hand now</th><th className="p-2.5 text-right">Reorder at</th></tr></thead>
        <tbody>{po.lines.map((l, i) => { const p = inv.products.find((x) => x.id === l.productId); const onHand = sum(inv.warehouses, (w) => qtyAt(map, l.productId, w.id)); return <tr key={i} className="border-t border-stone-200"><td className="p-2.5">{pSku(l.productId)} · {pName(l.productId)}</td><td className="p-2.5 text-right tabular-nums">{l.qty}</td><td className="p-2.5 text-right tabular-nums">{l.received}</td><td className="p-2.5 text-right tabular-nums">{Math.max(0, l.qty - l.received)}</td><td className={`p-2.5 text-right tabular-nums ${p && onHand <= p.reorder ? "font-semibold text-amber-700" : ""}`}>{onHand}</td><td className="p-2.5 text-right tabular-nums">{p?.reorder ?? "—"}</td></tr>; })}</tbody></table>
      <p className="border-t border-stone-200 px-3 py-2 text-sm text-slate-600">Recording a delivery adds stock movements to the shared Inventory data. <Link href="/erp-demos/inventory-warehouse-management/app" className="font-medium text-blue-700 underline">Open the Inventory demo</Link></p></Panel>
  </>);
}

const useP = () => { const [proc, setProc] = useSlice("proc"); const [inv] = useSlice("inv"); const [hrm] = useSlice("hrm"); const sName = (id: string) => proc.suppliers.find((s) => s.id === id)?.name ?? "?"; const pName = (id: string) => inv.products.find((p) => p.id === id)?.name ?? "?"; const pSku = (id: string) => inv.products.find((p) => p.id === id)?.sku ?? "?"; const eName = (id?: string) => hrm.employees.find((e) => e.id === id)?.name ?? "—"; return { proc, setProc, inv, hrm, sName, pName, pSku, eName }; };
const outstanding = (po: PurchaseOrder) => round2(sum(po.lines, (l) => Math.max(0, l.qty - l.received) * l.price));
const live = (po: PurchaseOrder) => po.status !== "Cancelled" && po.status !== "Draft" && po.status !== "Received";

function SupplierForm({ existing, onSave, onClose }: { existing?: Supplier; onSave(s: Omit<Supplier, "id">): void; onClose(): void }) {
  const [f, setF] = useState({ name: existing?.name ?? "", contact: existing?.contact ?? "", email: existing?.email ?? "", phone: existing?.phone ?? "", country: existing?.country ?? "", category: existing?.category ?? "", rating: String(existing?.rating ?? 3), terms: existing?.terms ?? "Net 30", status: existing?.status ?? ("Active" as Supplier["status"]), notes: existing?.notes ?? "" }); const [err, setErr] = useState<Record<string, string>>({});
  return (<Modal title={existing ? `Edit ${existing.name}` : "New supplier"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-supplier" onClick={() => { const e: Record<string, string> = {}; if (f.name.trim().length < 2) e.name = "Enter the supplier name"; if (!f.contact.trim()) e.contact = "Enter a contact person"; if (!emailOk(f.email)) e.email = "Enter a valid email"; if (!f.category.trim()) e.category = "Enter a category"; setErr(e); if (!Object.keys(e).length) onSave({ ...f, name: f.name.trim(), rating: Number(f.rating) }); }}>Save supplier</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Supplier name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} error={err.name} /><TextIn label="Contact person" value={f.contact} onChange={(e) => setF({ ...f, contact: e.target.value })} error={err.contact} /><TextIn label="Email" value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} error={err.email} /><TextIn label="Phone" value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })} /><TextIn label="Country" value={f.country} onChange={(e) => setF({ ...f, country: e.target.value })} /><TextIn label="Category" value={f.category} onChange={(e) => setF({ ...f, category: e.target.value })} error={err.category} />
      <SelectIn label="Payment terms" value={f.terms} onChange={(e) => setF({ ...f, terms: e.target.value })} options={["Net 15", "Net 30", "Net 45", "Net 60", "Prepaid"]} /><SelectIn label="Rating (1–5)" value={f.rating} onChange={(e) => setF({ ...f, rating: e.target.value })} options={["1", "2", "3", "4", "5"]} /><SelectIn label="Status" value={f.status} onChange={(e) => setF({ ...f, status: e.target.value as Supplier["status"] })} options={["Active", "On hold"]} /><AreaIn label="Notes" className="sm:col-span-2" value={f.notes} onChange={(e) => setF({ ...f, notes: e.target.value })} /></div></Modal>);
}
function Suppliers({ open }: { open(id: string): void }) {
  const { proc, setProc } = useP(); const toast = useToast(); const [form, setForm] = useState(false); const [status, setStatus] = useState(""); const [cat, setCat] = useState("");
  const rows = proc.suppliers.filter((s) => (!status || s.status === status) && (!cat || s.category === cat)); const spendOf = (id: string) => sum(proc.orders.filter((o) => o.supplierId === id && o.status !== "Cancelled" && o.status !== "Draft"), (o) => linesTotal(o.lines).total);
  const cols: Col<Supplier>[] = [{ key: "name", label: "Supplier", render: (s) => <span><span className="font-medium text-slate-900">{s.name}</span><span className="block text-xs text-slate-500">{s.contact} · {s.country}</span></span>, value: (s) => s.name }, { key: "category", label: "Category" }, { key: "terms", label: "Terms" }, { key: "rating", label: "Rating", render: (s) => "★".repeat(s.rating) + "☆".repeat(5 - s.rating), value: (s) => s.rating }, { key: "spend", label: "Order value", align: "right", value: (s) => spendOf(s.id), render: (s) => M(spendOf(s.id)) }, { key: "status", label: "Status", render: (s) => <Badge tone={s.status === "Active" ? "green" : "amber"}>{s.status}</Badge> }];
  return (<><PageHead title="Supplier directory" actions={<Btn kind="primary" onClick={() => setForm(true)} testid="new-supplier">+ New supplier</Btn>} /><DataTable rows={rows} columns={cols} rowKey={(s) => s.id} onRow={(s) => open(s.id)} exportName="procurement-suppliers" searchPlaceholder="Search suppliers…" toolbar={<><FilterSelect label="Status" value={status} onChange={setStatus} options={["Active", "On hold"]} /><FilterSelect label="Category" value={cat} onChange={setCat} options={[...new Set(proc.suppliers.map((s) => s.category))].sort()} /></>} testid="supplier-table" />
    {form && <SupplierForm onClose={() => setForm(false)} onSave={(rec) => { setProc((s) => ({ ...s, suppliers: [...s.suppliers, { id: uid("s"), ...rec }] })); logActivity("Procurement", `Supplier added: ${rec.name}`); toast("Supplier created"); setForm(false); }} />}</>);
}
function SupplierProfile({ id, back, openPo }: { id: string; back(): void; openPo(id: string): void }) {
  const { proc, setProc, pName } = useP(); const toast = useToast(); const s = proc.suppliers.find((x) => x.id === id); const [edit, setEdit] = useState(false);
  if (!s) return <Empty>Supplier not found. <Btn small onClick={back}>Back</Btn></Empty>;
  const orders = proc.orders.filter((o) => o.supplierId === id); const done = orders.filter((o) => o.status === "Received"); const onTime = done.filter((o) => (o.receipts.at(-1)?.date ?? "9") <= o.expected).length;
  const tx = [...orders.map((o) => ({ id: o.id, at: o.date, title: <button className="text-blue-700 hover:underline" onClick={() => openPo(o.id)}>{o.number}: {M(linesTotal(o.lines).total)} · {o.status}</button> })), ...orders.flatMap((o) => o.receipts.map((r) => ({ id: r.id + o.id, at: r.date, title: <span>Delivery {r.number} against {o.number}: {sum(r.lines, (l) => l.qty)} units ({r.lines.map((l) => pName(l.productId)).join(", ")})</span> })))].sort((a, b) => b.at.localeCompare(a.at));
  return (<><PageHead title={s.name} sub={`${s.category} · ${s.country} · ${s.terms}`} actions={<><Btn onClick={back}>← Suppliers</Btn><Btn onClick={() => setEdit(true)}>Edit</Btn><Btn onClick={() => { const n = s.status === "Active" ? "On hold" : "Active"; setProc((st) => ({ ...st, suppliers: st.suppliers.map((x) => (x.id === id ? { ...x, status: n } : x)) })); toast(`Supplier set to ${n}`); }} testid="toggle-hold">{s.status === "Active" ? "Put on hold" : "Reactivate"}</Btn></>} />
    <KpiRow><Kpi label="Status" value={s.status} /><Kpi label="Orders" value={orders.length} /><Kpi label="Order value" value={M(sum(orders.filter((o) => o.status !== "Cancelled" && o.status !== "Draft"), (o) => linesTotal(o.lines).total))} /><Kpi label="On-time deliveries" value={done.length ? pct(onTime / done.length) : "—"} sub={`${onTime} of ${done.length} completed orders`} /></KpiRow>
    <div className="mt-4 grid gap-4 lg:grid-cols-3"><Panel title="Contact"><dl className="space-y-1 text-sm"><dt className="text-xs text-slate-500">Contact</dt><dd>{s.contact}</dd><dt className="text-xs text-slate-500">Email</dt><dd>{s.email}</dd><dt className="text-xs text-slate-500">Phone</dt><dd>{s.phone}</dd><dt className="text-xs text-slate-500">Rating</dt><dd>{"★".repeat(s.rating)}{"☆".repeat(5 - s.rating)}</dd>{s.notes && <><dt className="text-xs text-slate-500">Notes</dt><dd>{s.notes}</dd></>}</dl></Panel><Panel title="Transaction history" className="lg:col-span-2"><Timeline items={tx.map((t) => ({ id: t.id, at: fmtDate(t.at), title: t.title }))} /></Panel></div>
    {edit && <SupplierForm existing={s} onClose={() => setEdit(false)} onSave={(rec) => { setProc((st) => ({ ...st, suppliers: st.suppliers.map((x) => (x.id === id ? { ...x, ...rec } : x)) })); toast("Supplier updated"); setEdit(false); }} />}</>);
}

/* ───────── Requisitions ───────── */
function LineEditor({ lines, setLines }: { lines: ReqLine[]; setLines(l: ReqLine[]): void }) {
  const { inv } = useP(); const set = (i: number, p: Partial<ReqLine>) => setLines(lines.map((l, k) => (k === i ? { ...l, ...p } : l)));
  return (<div><table className="w-full text-sm"><thead><tr className="text-left text-xs uppercase text-slate-500"><th>Product</th><th className="w-20">Qty</th><th className="w-28">Unit price</th><th className="w-28 text-right">Amount</th><th className="w-6" /></tr></thead><tbody>{lines.map((l, i) => <tr key={i}><td className="pr-2 pb-1"><select aria-label="Line product" className="w-full rounded border border-slate-300 px-1 py-1" value={l.productId} onChange={(e) => set(i, { productId: e.target.value, price: inv.products.find((p) => p.id === e.target.value)?.cost ?? l.price })}>{inv.products.map((p) => <option key={p.id} value={p.id}>{p.sku} · {p.name}</option>)}</select></td>
    <td className="pr-2"><input aria-label="Line quantity" type="number" min={1} className="w-full rounded border border-slate-300 px-2 py-1" value={l.qty} onChange={(e) => set(i, { qty: Number(e.target.value) })} /></td><td className="pr-2"><input aria-label="Line price" type="number" step="0.01" min={0} className="w-full rounded border border-slate-300 px-2 py-1" value={l.price} onChange={(e) => set(i, { price: Number(e.target.value) })} /></td><td className="text-right tabular-nums">{M(l.qty * l.price)}</td><td><button type="button" aria-label="Remove line" className="text-red-600" onClick={() => setLines(lines.filter((_, k) => k !== i))}>✕</button></td></tr>)}</tbody></table>
    <Btn small className="mt-2" testid="add-req-line" onClick={() => setLines([...lines, { productId: inv.products[0]?.id ?? "", qty: 1, price: inv.products[0]?.cost ?? 0 }])}>+ Add product</Btn></div>);
}
function ReqForm({ existing, onClose }: { existing?: Requisition; onClose(): void }) {
  const { proc, setProc, inv, hrm } = useP(); const toast = useToast(); const [lines, setLines] = useState<ReqLine[]>(existing?.lines ?? [{ productId: inv.products[0]?.id ?? "", qty: 1, price: inv.products[0]?.cost ?? 0 }]); const [f, setF] = useState({ requesterId: existing?.requesterId ?? "e22", justification: existing?.justification ?? "" }); const [err, setErr] = useState(""); const t = linesTotal(lines);
  const save = (submit: boolean) => { if (!lines.length) return setErr("Add at least one product."); if (lines.some((l) => !(l.qty >= 1 && Number.isInteger(l.qty)) || !(l.price >= 0))) return setErr("Quantities must be whole numbers of at least 1 and prices cannot be negative."); if (f.justification.trim().length < 5) return setErr("Add a short justification (5+ characters).");
    const dept = hrm.employees.find((e) => e.id === f.requesterId)?.dept ?? "Operations"; const status = submit ? "Submitted" : "Draft";
    if (existing) setProc((s) => ({ ...s, requisitions: s.requisitions.map((r) => (r.id === existing.id ? { ...r, ...f, dept, lines, status } : r)) })); else { const n = proc.nextNo.req; setProc((s) => ({ ...s, nextNo: { ...s.nextNo, req: n + 1 }, requisitions: [{ id: uid("rq"), number: `REQ-${n}`, date: DEMO_TODAY, ...f, dept, lines, status }, ...s.requisitions] })); logActivity("Procurement", `Requisition REQ-${n} ${submit ? "submitted" : "saved"} (${M(t.total)})`); }
    toast(submit ? "Requisition submitted for (simulated) approval" : "Requisition saved as draft"); onClose(); };
  return (<Modal title={existing ? `Edit ${existing.number}` : "New purchase requisition"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn onClick={() => save(false)} testid="save-req">Save draft</Btn><Btn kind="primary" onClick={() => save(true)} testid="submit-req">Submit for approval</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><SelectIn label="Requested by" value={f.requesterId} onChange={(e) => setF({ ...f, requesterId: e.target.value })} options={hrm.employees.filter((e) => e.status !== "Resigned").map((e) => ({ value: e.id, label: `${e.name} (${e.dept})` }))} /><TextIn label="Justification" value={f.justification} onChange={(e) => setF({ ...f, justification: e.target.value })} /></div>
    <div className="mt-4"><LineEditor lines={lines} setLines={setLines} /></div><p className="mt-3 text-right text-sm">Subtotal <b data-testid="req-subtotal">{M(t.subtotal)}</b> · Tax (8%, demo) {M(t.tax)} · Total <b className="font-display text-lg" data-testid="req-total">{M(t.total)}</b></p>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}
function decide(r: Requisition, status: "Approved" | "Rejected", note: string) { setDb((d) => ({ ...d, proc: { ...d.proc, requisitions: d.proc.requisitions.map((x) => (x.id === r.id ? { ...x, status, approverId: "e20", decidedAt: DEMO_TODAY, decisionNote: note } : x)) } })); logActivity("Procurement", `${r.number} ${status.toLowerCase()} (simulated)`); }
function Requisitions({ openPo, focus }: { openPo(id: string): void; focus?: string | null }) {
  const { proc, setProc, inv, eName, pName } = useP(); const toast = useToast(); const confirm = useConfirm(); const [form, setForm] = useState<Requisition | "new" | null>(null); const [status, setStatus] = useState(""); const [view, setView] = useState<string | null>(focus ?? null);
  const rows = proc.requisitions.filter((r) => !status || r.status === status); const r = proc.requisitions.find((x) => x.id === view);
  const convert = (rq: Requisition) => { const groups = groupBy(rq.lines, (l) => inv.products.find((p) => p.id === l.productId)?.supplierId ?? "s1"); let n = proc.nextNo.po; const made: PurchaseOrder[] = Object.entries(groups).map(([supplierId, ls]) => ({ id: uid("po"), number: `PO-${n++}`, supplierId, date: DEMO_TODAY, expected: addDays(DEMO_TODAY, 14), status: "Draft", lines: ls.map((l) => ({ productId: l.productId, qty: l.qty, price: l.price, received: 0 })), terms: proc.suppliers.find((s) => s.id === supplierId)?.terms ?? "Net 30", whId: "w1", reqId: rq.id, notes: `Created from ${rq.number}`, receipts: [] }));
    setProc((s) => ({ ...s, nextNo: { ...s.nextNo, po: n }, orders: [...made, ...s.orders], requisitions: s.requisitions.map((x) => (x.id === rq.id ? { ...x, status: "Converted", poId: made[0].id } : x)) })); logActivity("Procurement", `${rq.number} converted to ${made.map((m) => m.number).join(", ")}`); toast(`Converted to ${made.map((m) => m.number).join(" and ")}`); setView(null); openPo(made[0].id); };
  const cols: Col<Requisition>[] = [{ key: "number", label: "Requisition", render: (x) => <span className="font-medium">{x.number}</span> }, { key: "by", label: "Requested by", value: (x) => eName(x.requesterId) }, { key: "dept", label: "Department" }, { key: "date", label: "Date", render: (x) => fmtDate(x.date) }, { key: "total", label: "Total", align: "right", value: (x) => linesTotal(x.lines).total, render: (x) => M(linesTotal(x.lines).total) }, { key: "status", label: "Status", render: (x) => <Badge tone={rqTone(x.status)}>{x.status}</Badge> }];
  return (<><PageHead title="Purchase requisitions" sub="Request goods, submit for simulated approval, then convert approved requests into purchase orders." actions={<Btn kind="primary" onClick={() => setForm("new")} testid="new-req">+ New requisition</Btn>} />
    <DataTable rows={rows} columns={cols} rowKey={(x) => x.id} onRow={(x) => setView(x.id)} exportName="procurement-requisitions" toolbar={<FilterSelect label="Status" value={status} onChange={setStatus} options={["Draft", "Submitted", "Approved", "Rejected", "Converted"]} />} testid="req-table" />
    {r && <Drawer title={<span>{r.number}<span className="block text-xs font-normal text-slate-500">{eName(r.requesterId)} · {r.dept}</span></span>} onClose={() => setView(null)} footer={<>
      {r.status === "Draft" && <><Btn onClick={() => { setForm(r); setView(null); }}>Edit</Btn><Btn kind="primary" testid="submit-draft" onClick={() => { setProc((s) => ({ ...s, requisitions: s.requisitions.map((x) => (x.id === r.id ? { ...x, status: "Submitted" } : x)) })); logActivity("Procurement", `${r.number} submitted (simulated)`); toast("Submitted for (simulated) approval"); }}>Submit for approval</Btn><Btn kind="danger" onClick={async () => { if (await confirm(`Delete ${r.number}?`)) { setProc((s) => ({ ...s, requisitions: s.requisitions.filter((x) => x.id !== r.id) })); setView(null); toast("Requisition deleted", "amber"); } }}>Delete</Btn></>}
      {r.status === "Submitted" && <><Btn kind="primary" onClick={() => { decide(r, "Approved", "Approved from the requisition view."); toast(`${r.number} approved (simulated)`); }}>Approve</Btn><Btn kind="danger" onClick={() => { decide(r, "Rejected", "Rejected from the requisition view."); toast(`${r.number} rejected (simulated)`, "amber"); }}>Reject</Btn></>}
      {r.status === "Approved" && <Btn kind="primary" onClick={() => convert(r)} testid="convert-po">Convert to purchase order</Btn>}{r.status === "Converted" && r.poId && <Btn onClick={() => openPo(r.poId!)}>Open purchase order</Btn>}</>}>
      <Badge tone={rqTone(r.status)}>{r.status}</Badge><p className="mt-2 text-sm">{r.justification}</p>
      <table className="mt-3 w-full text-sm"><thead className="text-left text-[11px] uppercase text-slate-500"><tr><th>Product</th><th className="text-right">Qty</th><th className="text-right">Price</th><th className="text-right">Amount</th></tr></thead><tbody>{r.lines.map((l, i) => <tr key={i} className="border-t border-slate-100"><td className="py-1">{pName(l.productId)}</td><td className="text-right">{l.qty}</td><td className="text-right">{M(l.price)}</td><td className="text-right">{M(l.qty * l.price)}</td></tr>)}</tbody></table>
      <p className="mt-2 text-right text-sm">Subtotal {M(linesTotal(r.lines).subtotal)} · Tax {M(linesTotal(r.lines).tax)} · <b>Total {M(linesTotal(r.lines).total)}</b></p>
      {r.decidedAt && <div className="mt-4 rounded-lg bg-slate-50 p-3 text-sm"><p className="text-xs font-semibold uppercase text-slate-500">Simulated decision</p><p>{r.status === "Rejected" ? "Rejected" : "Approved"} by {eName(r.approverId)} on {fmtDate(r.decidedAt)}</p><p className="text-slate-600">{r.decisionNote}</p></div>}</Drawer>}
    {form && <ReqForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} />}</>);
}
function Approvals() {
  const { proc, eName, pName } = useP(); const toast = useToast(); const [note, setNote] = useState<Record<string, string>>({}); const queue = proc.requisitions.filter((r) => r.status === "Submitted"); const hist = proc.requisitions.filter((r) => r.decidedAt).sort((a, b) => (b.decidedAt ?? "").localeCompare(a.decidedAt ?? ""));
  return (<><PageHead title="Approval queue" sub="Simulated approvals: deciding here only changes records in this demo." /><Notice tone="blue">Approver in this demo: Victor Novak (Operations Manager). No email or notification is sent.</Notice>
    <div className="mt-4 space-y-3" data-testid="approval-queue">{queue.map((r) => <Panel key={r.id} title={<span>{r.number} · {eName(r.requesterId)} <span className="font-normal text-slate-500">({r.dept})</span></span>} actions={<Badge tone="amber">{M(linesTotal(r.lines).total)}</Badge>}>
      <p className="text-sm text-slate-600">{r.justification}</p><ul className="mt-1 text-sm">{r.lines.map((l, i) => <li key={i}>{l.qty} × {pName(l.productId)} @ {M(l.price)}</li>)}</ul>
      <div className="mt-3 flex flex-wrap items-center gap-2"><input aria-label={`Decision note for ${r.number}`} value={note[r.id] ?? ""} onChange={(e) => setNote({ ...note, [r.id]: e.target.value })} placeholder="Decision note (optional)" className="min-w-48 flex-1 rounded-md border border-slate-300 px-2 py-1.5 text-sm" /><Btn kind="primary" aria-label={`Approve ${r.number}`} onClick={() => { decide(r, "Approved", note[r.id] || "Approved."); toast(`${r.number} approved (simulated)`); }}>Approve</Btn><Btn kind="danger" aria-label={`Reject ${r.number}`} onClick={() => { decide(r, "Rejected", note[r.id] || "Rejected."); toast(`${r.number} rejected (simulated)`, "amber"); }}>Reject</Btn></div></Panel>)}{queue.length === 0 && <Empty>The approval queue is empty.</Empty>}</div>
    <Panel title="Decision history" className="mt-4"><Timeline items={hist.map((r) => ({ id: r.id, at: fmtDate(r.decidedAt ?? ""), tone: r.status === "Rejected" ? "red" : undefined, title: `${r.number} ${r.status === "Rejected" ? "rejected" : "approved"} by ${eName(r.approverId)} (${M(linesTotal(r.lines).total)})`, sub: r.decisionNote }))} /></Panel></>);
}

/* ───────── Orders ───────── */
function Orders({ open }: { open(id: string): void }) {
  const { proc, setProc, inv, sName } = useP(); const toast = useToast(); const [sup, setSup] = useState(""); const [status, setStatus] = useState(""); const [form, setForm] = useState(false);
  const rows = proc.orders.filter((o) => (!sup || o.supplierId === sup) && (!status || o.status === status));
  const cols: Col<PurchaseOrder>[] = [{ key: "number", label: "PO", render: (o) => <span className="font-medium">{o.number}</span> }, { key: "sup", label: "Supplier", value: (o) => sName(o.supplierId) }, { key: "date", label: "Ordered", render: (o) => fmtDate(o.date) }, { key: "expected", label: "Expected", render: (o) => <span className={live(o) && o.expected < DEMO_TODAY ? "font-semibold text-red-700" : ""}>{fmtDate(o.expected)}</span> }, { key: "total", label: "Total", align: "right", value: (o) => linesTotal(o.lines).total, render: (o) => M(linesTotal(o.lines).total) }, { key: "rec", label: "Received", align: "right", value: (o) => { const q = sum(o.lines, (l) => l.qty); return q ? sum(o.lines, (l) => l.received) / q : 0; }, render: (o) => pct(sum(o.lines, (l) => l.received) / Math.max(1, sum(o.lines, (l) => l.qty))) }, { key: "status", label: "Status", render: (o) => <Badge tone={poTone(o.status)}>{o.status}</Badge> }];
  return (<><PageHead title="Purchase orders" actions={<Btn kind="primary" onClick={() => setForm(true)} testid="new-po">+ New purchase order</Btn>} /><DataTable rows={rows} columns={cols} rowKey={(o) => o.id} onRow={(o) => open(o.id)} exportName="procurement-orders" defaultSort={{ key: "date", dir: -1 }} toolbar={<><FilterSelect label="Supplier" value={sup} onChange={setSup} options={proc.suppliers.map((s) => ({ value: s.id, label: s.name }))} /><FilterSelect label="Status" value={status} onChange={setStatus} options={["Draft", "Sent", "Partially received", "Received", "Cancelled"]} /></>} testid="po-table" />
    {form && <PoForm onClose={() => setForm(false)} onSave={(po) => { setProc((s) => ({ ...s, nextNo: { ...s.nextNo, po: s.nextNo.po + 1 }, orders: [po, ...s.orders] })); logActivity("Procurement", `${po.number} created`); toast(`${po.number} created as draft`); setForm(false); open(po.id); }} />}{void inv}</>);
}
function PoForm({ onClose, onSave }: { onClose(): void; onSave(po: PurchaseOrder): void }) {
  const { proc, inv } = useP(); const [f, setF] = useState({ supplierId: proc.suppliers.find((s) => s.status === "Active")?.id ?? "s1", expected: addDays(DEMO_TODAY, 14), whId: "w1" }); const [lines, setLines] = useState<ReqLine[]>([{ productId: inv.products[0]?.id ?? "", qty: 1, price: inv.products[0]?.cost ?? 0 }]); const [err, setErr] = useState(""); const sup = proc.suppliers.find((s) => s.id === f.supplierId);
  return (<Modal title="New purchase order" wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-po" onClick={() => { if (sup?.status === "On hold") return setErr(`${sup.name} is on hold. Reactivate the supplier first.`); if (!lines.length || lines.some((l) => !(l.qty >= 1 && Number.isInteger(l.qty)) || !(l.price >= 0))) return setErr("Add products with whole-number quantities (1+) and valid prices."); if (f.expected < DEMO_TODAY) return setErr("The expected delivery date cannot be in the past."); onSave({ id: uid("po"), number: `PO-${proc.nextNo.po}`, supplierId: f.supplierId, date: DEMO_TODAY, expected: f.expected, status: "Draft", lines: lines.map((l) => ({ ...l, received: 0 })), terms: sup?.terms ?? "Net 30", whId: f.whId, notes: "", receipts: [] }); }}>Create purchase order</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-3"><SelectIn label="Supplier" value={f.supplierId} onChange={(e) => setF({ ...f, supplierId: e.target.value })} options={proc.suppliers.map((s) => ({ value: s.id, label: s.name + (s.status === "On hold" ? " (on hold)" : "") }))} /><TextIn label="Expected delivery" type="date" value={f.expected} onChange={(e) => setF({ ...f, expected: e.target.value })} /><SelectIn label="Deliver to warehouse" value={f.whId} onChange={(e) => setF({ ...f, whId: e.target.value })} options={inv.warehouses.map((w) => ({ value: w.id, label: w.name }))} /></div>
    <div className="mt-4"><LineEditor lines={lines} setLines={setLines} /></div><p className="mt-3 text-right text-sm">Total incl. 8% tax (demo): <b className="font-display text-lg">{M(linesTotal(lines).total)}</b></p>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}
function PoDetail({ id, back }: { id: string; back(): void }) {
  const { proc, setProc, inv, sName, pName, pSku } = useP(); const toast = useToast(); const confirm = useConfirm(); const po = proc.orders.find((o) => o.id === id); const [rec, setRec] = useState(false); const [preview, setPreview] = useState(false);
  if (!po) return <Empty>Purchase order not found. <Btn small onClick={back}>Back</Btn></Empty>;
  const t = linesTotal(po.lines); const sup = proc.suppliers.find((s) => s.id === po.supplierId); const whName = inv.warehouses.find((w) => w.id === po.whId)?.name;
  const setStatus = (status: PurchaseOrder["status"]) => { setProc((s) => ({ ...s, orders: s.orders.map((o) => (o.id === id ? { ...o, status } : o)) })); logActivity("Procurement", `${po.number} → ${status}`); toast(status === "Sent" ? `${po.number} marked as sent (simulated: nothing was emailed)` : `${po.number} → ${status}`); };
  return (<><PageHead title={`${po.number}: ${sName(po.supplierId)}`} sub={`Ordered ${fmtDate(po.date)} · expected ${fmtDate(po.expected)} · ${po.terms} · deliver to ${whName}`} actions={<><Btn onClick={back}>← Orders</Btn><Btn onClick={() => setPreview(true)} testid="preview-po">Preview / print</Btn>
    {po.status === "Draft" && <><Btn kind="primary" onClick={() => setStatus("Sent")} testid="send-po">Send to supplier (simulated)</Btn><Btn kind="danger" onClick={async () => { if (await confirm(`Delete ${po.number}?`)) { setProc((s) => ({ ...s, orders: s.orders.filter((o) => o.id !== id) })); toast("Draft deleted", "amber"); back(); } }}>Delete draft</Btn></>}
    {(po.status === "Sent" || po.status === "Partially received") && <><Btn kind="primary" onClick={() => setRec(true)} testid="record-delivery">Record delivery</Btn>{po.status === "Sent" && <Btn kind="danger" onClick={async () => { if (await confirm(`Cancel ${po.number}?`)) setStatus("Cancelled"); }}>Cancel order</Btn>}</>}</>} />
    <div className="grid gap-4 lg:grid-cols-3"><Panel title="Status"><Badge tone={poTone(po.status)}>{po.status}</Badge><dl className="mt-3 space-y-1 text-sm"><div className="flex justify-between"><dt className="text-slate-500">Subtotal</dt><dd>{M(t.subtotal)}</dd></div><div className="flex justify-between"><dt className="text-slate-500">Tax (8%, demo)</dt><dd>{M(t.tax)}</dd></div><div className="flex justify-between font-semibold"><dt>Total</dt><dd data-testid="po-total">{M(t.total)}</dd></div><div className="flex justify-between"><dt className="text-slate-500">Outstanding</dt><dd data-testid="po-outstanding">{M(outstanding(po))}</dd></div></dl>{po.notes && <p className="mt-2 text-xs text-slate-500">{po.notes}</p>}</Panel>
      <Panel title="Order lines" className="lg:col-span-2" pad={false}><table className="w-full text-sm" data-testid="po-lines"><thead className="bg-slate-50 text-left text-[11px] uppercase text-slate-500"><tr><th className="p-2">Product</th><th className="p-2 text-right">Ordered</th><th className="p-2 text-right">Received</th><th className="p-2 text-right">Outstanding</th><th className="p-2 text-right">Price</th></tr></thead><tbody>{po.lines.map((l, i) => <tr key={i} className="border-t border-slate-100"><td className="p-2">{pSku(l.productId)} · {pName(l.productId)}</td><td className="p-2 text-right">{l.qty}</td><td className="p-2 text-right" data-testid={`recv-${l.productId}`}>{l.received}</td><td className="p-2 text-right">{Math.max(0, l.qty - l.received)}</td><td className="p-2 text-right">{M(l.price)}</td></tr>)}</tbody></table></Panel>
      <Panel title="Goods receipts" className="lg:col-span-3"><Timeline items={po.receipts.map((r) => ({ id: r.id, at: fmtDate(r.date), title: `${r.number}: ${r.lines.map((l) => `${l.qty} × ${pName(l.productId)}`).join(", ")}`, sub: r.note }))} /></Panel></div>
    {rec && <ReceiveForm po={po} onClose={() => setRec(false)} />}
    {preview && <Modal title={`Purchase order ${po.number}`} wide onClose={() => setPreview(false)} footer={<Btn kind="primary" onClick={printNow} testid="print-po">Print</Btn>}><PrintSheet><div className="flex justify-between"><div><h2 className="font-display text-2xl font-semibold">PURCHASE ORDER</h2><p className="text-sm text-slate-500">{po.number}{po.status === "Draft" ? " · DRAFT" : ""}</p></div><div className="text-right text-sm"><p className="font-semibold">NorthPeak Software Ltd (fictional)</p><p className="text-slate-500">Date {fmtDate(po.date)}<br />Deliver by {fmtDate(po.expected)} to {whName}</p></div></div><div className="mt-4 text-sm"><p className="text-xs uppercase text-slate-500">Supplier</p><p className="font-semibold">{sup?.name}</p><p className="text-slate-500">{sup?.contact} · {sup?.email}</p></div>
      <table className="mt-4 w-full text-sm"><thead><tr className="border-b-2 border-slate-300 text-left text-xs uppercase text-slate-500"><th className="py-1">Item</th><th className="text-right">Qty</th><th className="text-right">Unit price</th><th className="text-right">Amount</th></tr></thead><tbody>{po.lines.map((l, i) => <tr key={i} className="border-b border-slate-100"><td className="py-1">{pSku(l.productId)} · {pName(l.productId)}</td><td className="text-right">{l.qty}</td><td className="text-right">{M(l.price)}</td><td className="text-right">{M(l.qty * l.price)}</td></tr>)}</tbody></table>
      <dl className="ml-auto mt-3 grid w-64 grid-cols-2 gap-1 text-sm"><dt>Subtotal</dt><dd className="text-right">{M(t.subtotal)}</dd><dt>Tax (8%)</dt><dd className="text-right">{M(t.tax)}</dd><dt className="border-t pt-1 font-semibold">Total</dt><dd className="border-t pt-1 text-right font-semibold">{M(t.total)}</dd></dl><p className="mt-5 text-xs text-slate-400">Payment terms: {po.terms}. Demonstration document with fictional data; it has not been sent to any supplier.</p></PrintSheet></Modal>}</>);
}
function ReceiveForm({ po, onClose }: { po: PurchaseOrder; onClose(): void }) {
  const { proc, inv, pName } = useP(); const toast = useToast(); const [qty, setQty] = useState<Record<string, string>>({}); const [wh, setWh] = useState(po.whId); const [note, setNote] = useState(""); const [err, setErr] = useState("");
  const submit = () => {
    const lines = po.lines.map((l) => ({ productId: l.productId, qty: Number(qty[l.productId] || 0), out: l.qty - l.received })).filter((l) => l.qty !== 0);
    if (lines.length === 0) return setErr("Enter a delivered quantity for at least one line."); const bad = lines.find((l) => !Number.isInteger(l.qty) || l.qty < 0 || l.qty > l.out); if (bad) return setErr(`${pName(bad.productId)}: the delivered quantity must be a whole number between 1 and the ${bad.out} still outstanding.`);
    const n = proc.nextNo.grn; const rcpt = { id: uid("rc"), number: `GRN-${po.number.slice(3)}-${po.receipts.length + 1}`, date: DEMO_TODAY, whId: wh, by: "e21", note: note || "Delivery recorded", lines: lines.map((l) => ({ productId: l.productId, qty: l.qty })) };
    setDb((d) => { const orders = d.proc.orders.map((o) => { if (o.id !== po.id) return o; const nl = o.lines.map((l) => ({ ...l, received: l.received + (lines.find((x) => x.productId === l.productId)?.qty ?? 0) })); const done = nl.every((l) => l.received >= l.qty); return { ...o, lines: nl, receipts: [...o.receipts, rcpt], status: done ? ("Received" as const) : ("Partially received" as const) }; });
      const moves = lines.map((l, i) => ({ id: `m${Date.now()}${i}`, date: DEMO_TODAY, productId: l.productId, whId: wh, type: "Receipt" as const, qty: l.qty, unitCost: po.lines.find((x) => x.productId === l.productId)?.price, ref: rcpt.number, note: `Goods received against ${po.number}` }));
      return { ...d, proc: { ...d.proc, orders, nextNo: { ...d.proc.nextNo, grn: n + 1 } }, inv: { ...d.inv, movements: [...d.inv.movements, ...moves] } }; });
    logActivity("Procurement", `${rcpt.number}: ${sum(lines, (l) => l.qty)} units received against ${po.number} (inventory updated)`); toast(`Delivery recorded: ${sum(lines, (l) => l.qty)} units added to ${inv.warehouses.find((w) => w.id === wh)?.name} stock`); onClose();
  };
  return (<Modal title={`Record delivery: ${po.number}`} onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" onClick={submit} testid="save-receipt">Record delivery</Btn></>}>
    <Notice tone="blue">Simulated delivery. Recording it adds the quantities to the Inventory demo&apos;s stock for the chosen warehouse.</Notice>
    <table className="mt-3 w-full text-sm"><thead className="text-left text-[11px] uppercase text-slate-500"><tr><th>Product</th><th className="text-right">Outstanding</th><th className="w-28">Delivered now</th></tr></thead><tbody>{po.lines.map((l) => <tr key={l.productId} className="border-t border-slate-100"><td className="py-1.5">{pName(l.productId)}</td><td className="text-right">{l.qty - l.received}</td><td><input aria-label={`Delivered ${pName(l.productId)}`} type="number" min={0} disabled={l.qty - l.received <= 0} value={qty[l.productId] ?? ""} onChange={(e) => setQty({ ...qty, [l.productId]: e.target.value })} className="w-full rounded border border-slate-300 px-2 py-1" /></td></tr>)}</tbody></table>
    <div className="mt-3 grid gap-3 sm:grid-cols-2"><SelectIn label="Receive into warehouse" value={wh} onChange={(e) => setWh(e.target.value)} options={inv.warehouses.map((w) => ({ value: w.id, label: w.name }))} /><TextIn label="Delivery note" value={note} onChange={(e) => setNote(e.target.value)} /></div>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}

/* ───────── Receipts & reports ───────── */
function Receipts({ openPo }: { openPo(id: string): void }) {
  const { proc, sName } = useP(); const rows = proc.orders.flatMap((o) => o.receipts.map((r) => ({ ...r, po: o, units: sum(r.lines, (l) => l.qty) }))).sort((a, b) => b.date.localeCompare(a.date));
  const cols: Col<(typeof rows)[number]>[] = [{ key: "number", label: "Receipt" }, { key: "date", label: "Date", render: (r) => fmtDate(r.date) }, { key: "po", label: "Purchase order", value: (r) => r.po.number, render: (r) => <button className="text-blue-700 hover:underline" onClick={() => openPo(r.po.id)}>{r.po.number}</button> }, { key: "sup", label: "Supplier", value: (r) => sName(r.po.supplierId) }, { key: "units", label: "Units", align: "right" }, { key: "note", label: "Note" }];
  return (<><PageHead title="Goods receipt records" sub="Every recorded delivery. Each one also created stock movements in the Inventory demo." /><DataTable rows={rows} columns={cols} rowKey={(r) => r.id} exportName="procurement-receipts" testid="receipt-table" /></>);
}
function Reports() {
  const { proc, sName, pName } = useP(); const [tab, setTab] = useState("supplier"); const orders = proc.orders.filter((o) => o.status !== "Cancelled" && o.status !== "Draft");
  const bySup = proc.suppliers.map((s) => { const os = orders.filter((o) => o.supplierId === s.id); const done = os.filter((o) => o.status === "Received"); const onTime = done.filter((o) => (o.receipts.at(-1)?.date ?? "9") <= o.expected).length; return { s, n: os.length, value: round2(sum(os, (o) => linesTotal(o.lines).total)), onTime: done.length ? onTime / done.length : null }; }).filter((x) => x.n > 0);
  const months = lastNMonths(6); const byMonth = months.map((m) => ({ label: monthLabel(m), values: { value: sum(orders.filter((o) => monthKey(o.date) === m), (o) => linesTotal(o.lines).total) } }));
  const exportPo = () => downloadCsv("procurement-purchase-orders", [["PO", "Supplier", "Date", "Expected", "Status", "Product", "Ordered", "Received", "Unit price", "Line total"], ...proc.orders.flatMap((o) => o.lines.map((l) => [o.number, sName(o.supplierId), o.date, o.expected, o.status, pName(l.productId), l.qty, l.received, l.price, round2(l.qty * l.price)]))]);
  return (<><PageHead title="Procurement reports" sub="Calculated from purchase orders and goods receipts." actions={<><Btn onClick={exportPo} testid="export-po">Export purchase orders CSV</Btn><Btn onClick={() => downloadJson("procurement-report", { suppliers: bySup.map((x) => ({ supplier: x.s.name, orders: x.n, value: x.value, onTimeRate: x.onTime })), orders: proc.orders })} testid="export-po-json">JSON</Btn></>} />
    <Tabs value={tab} onChange={setTab} tabs={[{ id: "supplier", label: "By supplier" }, { id: "month", label: "Spend by month" }]} />
    <div className="mt-3">{tab === "supplier" ? <Panel pad={false}><table className="w-full text-sm"><thead className="bg-slate-50 text-left text-[11px] uppercase text-slate-500"><tr><th className="p-2">Supplier</th><th className="p-2 text-right">Orders</th><th className="p-2 text-right">Order value</th><th className="p-2 text-right">On-time rate</th></tr></thead><tbody>{bySup.map((x) => <tr key={x.s.id} className="border-t"><td className="p-2 font-medium">{x.s.name}</td><td className="p-2 text-right">{x.n}</td><td className="p-2 text-right tabular-nums">{M(x.value)}</td><td className="p-2 text-right">{x.onTime == null ? "n/a" : pct(x.onTime)}</td></tr>)}</tbody><tfoot className="border-t-2 bg-slate-50 font-semibold"><tr><td className="p-2">Total</td><td className="p-2 text-right">{sum(bySup, (x) => x.n)}</td><td className="p-2 text-right tabular-nums" data-testid="report-total">{M(sum(bySup, (x) => x.value))}</td><td /></tr></tfoot></table></Panel> : <Panel title="Committed order value by month"><BarChart ariaLabel="Spend by month" data={byMonth} series={[{ key: "value", label: "Order value" }]} fmt={moneyK} /></Panel>}</div><p className="mt-2 text-xs text-slate-500">{void daysBetween}Orders in draft or cancelled status are excluded. Tax is a demo assumption (8%).</p></>);
}

